{
  "id": "a22b1f83-2c1d-4135-93b2-ed99881ed447",
  "version": "1.8",
  "name": "BillingInvoiceLookup",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "370a73a9-dc4d-4bc1-adae-7a5e0876dd86",
