      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Data passed when manually triggering the workflow.",
          "source": "=result.response",
          "var": "output"
        }
      }
    },
    {
      "id": "normalizeInput",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Normalize Invoice Number"
      },
      "inputs": {
        "script": "var raw = $vars.invoiceNumber || '';\nvar trimmed = raw.trim().toUpperCase();\nvar normalized = trimmed.startsWith('MCS-') ? trimmed : ('MCS-' + trimmed);\nreturn { normalizedInvoiceNumber: normalized };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=result.Error",
          "var": "error"
        }
      }
    },
    {
      "id": "queryBillingdisputeerp1",
      "type": "uipath.connector.uipath-uipath-dataservice.query-entity-records",
      "typeVersion": "1.0.0",
      "display": {
        "label": "Query BillingDisputeERP"
      },
      "inputs": {
        "detail": {
          "connector": "uipath-uipath-dataservice",
          "connectionId": "d61e5d0e-04af-4f93-95cc-151d81fa08dc",
          "connectionResourceId": "d61e5d0e-04af-4f93-95cc-151d81fa08dc",
          "connectionFolderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
          "method": "POST",
          "endpoint": "/v2/BillingDisputeERP/qer",
          "queryParameters": {
            "entityName": "BillingDisputeERP",
